import React from "react";
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import {
  Link,
  Navigate,
  Outlet,
  useLocation,
  useNavigate,
} from "react-router-dom";
import CssBaseline from "@mui/material/CssBaseline";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

import {
  Alert,
  AppBar,
  Avatar,
  Badge,
  Box,
  Button,
  CircularProgress,
  Checkbox,
  Chip,
  Container,
  Divider,
  Drawer,
  FormControlLabel,
  Grid,
  IconButton,
  InputBase,
  LinearProgress,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Select,
  Snackbar,
  Stack,
  Switch,
  Tab,
  Tabs,
  TextField,
  Toolbar,
  Typography,
  useMediaQuery,
} from "@mui/material";

import {
  ThemeProvider as MuiThemeProvider,
  createTheme,
} from "@mui/material/styles";

import { AnimatePresence, motion } from "framer-motion";

import {
  MdAdd,
  MdArrowBack,
  MdArrowForward,
  MdAutoAwesome,
  MdCheckCircle,
  MdDownload,
  MdError,
  MdLightMode,
  MdRefresh,
  MdSave,
  MdCancel,
  MdCloudUpload,
  MdDarkMode,
  MdDelete,
  MdDescription,
  MdEdit,
  MdLightbulb,
  MdLock,
  MdLogout,
  MdMenu,
  MdMic,
  MdNotifications,
  MdPerson,
  MdSearch,
  MdSettings,
  MdSpaceDashboard,
  MdStop,
  MdTrendingUp,
  MdUploadFile,
  MdWorkOutline,
} from "react-icons/md";

import { FcGoogle } from "react-icons/fc";
import AIVideoInterview from "./pages/AIVideoInterview";

const PRINT_CSS = `
@media print {
  body * {
    visibility: hidden !important;
  }

  .resume-preview,
  .resume-preview * {
    visibility: visible !important;
  }

  .resume-preview {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 !important;
    padding: 18mm !important;
    border: none !important;
    box-shadow: none !important;
    background: white !important;
  }

  @page {
    size: A4;
    margin: 0;
  }
}
`;

/* ============================================================
GLOBAL STYLES
============================================================ */

const GLOBAL_CSS = ` {
--font-display: 'Sora', 'Inter', sans-serif;
--font-body: 'Inter', sans-serif;
}

{
box-sizing: border-box;
}

html,
body {
margin: 0;
padding: 0;
font-family: var(--font-body);
scroll-behavior: smooth;
}

#root {
min-height: 100vh;
}

::-webkit-scrollbar {
width: 8px;
height: 8px;
}

::-webkit-scrollbar-track {
background: transparent;
}

::-webkit-scrollbar-thumb {
background: rgba(124, 58, 237, 0.35);
border-radius: 8px;
}

::-webkit-scrollbar-thumb {
background: rgba(124, 58, 237, 0.55);
}

a {
text-decoration: none;
color: inherit;
}

.glass {
background: rgba(255, 255, 255, 0.06);
backdrop-filter: blur(18px);
-webkit-backdrop-filter: blur(18px);
border: 1px solid rgba(255, 255, 255, 0.12);
}

.glass-light {
background: rgba(255, 255, 255, 0.7);
backdrop-filter: blur(18px);
-webkit-backdrop-filter: blur(18px);
border: 1px solid rgba(15, 23, 42, 0.06);
}

.gradient-text {
background: linear-gradient(
120deg,
#2563EB 0%,
#7C3AED 55%,
#06B6D4 100%
);

-webkit-background-clip: text;
background-clip: text;
-webkit-text-fill-color: transparent;
}

.aurora-bg {
position: fixed;
inset: 0;
z-index: -1;
overflow: hidden;
pointer-events: none;
}

.aurora-blob {
position: absolute;
border-radius: 50%;
filter: blur(90px);
opacity: 0.45;
}
`;

function GlobalStyleTag() {
  return (
    <style
      dangerouslySetInnerHTML={{
        __html: GLOBAL_CSS + PRINT_CSS,
      }}
    />
  );
}

/* ============================================================
GOOGLE FONTS
============================================================ */

function useGoogleFonts() {
  useEffect(() => {
    const link = document.createElement("link");

    link.rel = "stylesheet";

    link.href =
      "https://fonts.googleapis.com/css2?family=Sora:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap";

    document.head.appendChild(link);

    return () => {
      document.head.removeChild(link);
    };
  }, []);
}

/* ============================================================
THEME
============================================================ */

const brand = {
  primary: "#2563EB",
  secondary: "#7C3AED",
  accent: "#06B6D4",
  bgLight: "#F8FAFC",
  bgDark: "#0F172A",
};

function buildTheme(mode) {
  const isDark = mode === "dark";

  return createTheme({
    palette: {
      mode,

      primary: {
        main: brand.primary,
      },

      secondary: {
        main: brand.secondary,
      },

      info: {
        main: brand.accent,
      },

      background: {
        default: isDark ? brand.bgDark : brand.bgLight,

        paper: isDark ? "#141B2E" : "#FFFFFF",
      },

      text: {
        primary: isDark ? "#E7ECF7" : "#0F172A",

        secondary: isDark ? "#94A3B8" : "#475569",
      },
    },

    typography: {
      fontFamily: "Inter, sans-serif",

      h1: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 800,
      },

      h2: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 700,
      },

      h3: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 700,
      },

      h4: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 700,
      },

      h5: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 600,
      },

      h6: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 600,
      },

      button: {
        fontFamily: "Sora, sans-serif",
        fontWeight: 600,
        textTransform: "none",
      },
    },

    shape: {
      borderRadius: 16,
    },

    components: {
      MuiButton: {
        styleOverrides: {
          root: {
            borderRadius: 12,
            padding: "10px 22px",
          },

          containedPrimary: {
            backgroundImage: `linear-gradient(120deg, ${brand.primary}, ${brand.secondary})`,

            boxShadow: "0 8px 24px rgba(37, 99, 235, 0.28)",

            "&:hover": {
              boxShadow: "0 10px 30px rgba(124, 58, 237, 0.38)",
            },
          },
