/* ============================================================
UPLOAD RESUME
============================================================ */

function UploadResume() {
  const navigate = useNavigate();

  const [file, setFile] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [backendStatus, setBackendStatus] = useState(null);

  const MAX_FILE_SIZE = 5 * 1024 * 1024;

  const validateFile = (selectedFile) => {
    if (!selectedFile) {
      return "Please select a PDF resume.";
    }

    const isPdf =
      selectedFile.type === "application/pdf" ||
      selectedFile.name.toLowerCase().endsWith(".pdf");

    if (!isPdf) {
      return "Only PDF files are supported.";
    }

    if (selectedFile.size > MAX_FILE_SIZE) {
      return "File is too large. Maximum size is 5 MB.";
    }

    return "";
  };

  const handleFile = (selectedFile) => {
    setError("");

    const validationError = validateFile(selectedFile);

    if (validationError) {
      setFile(null);
      setError(validationError);
      return;
    }

    setFile(selectedFile);
  };

  const handleInputChange = (event) => {
    const selectedFile = event.target.files?.[0];

    if (selectedFile) {
      handleFile(selectedFile);
    }
  };

  const handleDrop = (event) => {
    event.preventDefault();
    event.stopPropagation();

    setDragActive(false);

    const droppedFile = event.dataTransfer.files?.[0];

    if (droppedFile) {
      handleFile(droppedFile);
    }
  };

  const handleDragOver = (event) => {
    event.preventDefault();
    event.stopPropagation();

    setDragActive(true);
  };

  const handleDragLeave = (event) => {
    event.preventDefault();
    event.stopPropagation();

    setDragActive(false);
  };

  const checkHealth = async () => {
    try {
      setBackendStatus("checking");

      const response = await fetch(HEALTH_URL);

      if (!response.ok) {
        throw new Error(`Backend returned ${response.status}`);
      }

      const data = await response.json();

      if (data.model_loaded === false) {
        throw new Error("Backend is running, but the ML model is not loaded.");
      }

      setBackendStatus("connected");

      return true;
    } catch (err) {
      console.error("Backend health check failed:", err);

      setBackendStatus("error");

      setError(`Cannot connect to backend at ${API_BASE_URL}. ${err.message}`);

      return false;
    }
  };

  useEffect(() => {
    checkHealth();
  }, []);

  const handleAnalyze = async () => {
    setError("");

    if (!file) {
      setError("Please select a PDF resume first.");
      return;
    }

    const validationError = validateFile(file);

    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);

    try {
      /*
       * Check backend before uploading.
       */
      const healthy = await checkHealth();

      if (!healthy) {
        return;
      }

      /*
       * Build multipart request.
       *
       * IMPORTANT:
       * Backend expects:
       *
       * request.files["file"]
       *
       * Therefore the field name MUST be "file".
       */
      const formData = new FormData();

      formData.append("file", file);

      const response = await fetch(PREDICT_URL, {
        method: "POST",
        body: formData,
      });

      let data = null;

      try {
        data = await response.json();
      } catch {
        throw new Error(
          `Backend returned an invalid response (${response.status}).`,
        );
      }

      if (!response.ok) {
        throw new Error(
          data?.message ||
            data?.error ||
            `Resume analysis failed (${response.status}).`,
        );
      }

      if (data.success === false) {
        throw new Error(
          data.message || data.error || "Resume analysis failed.",
        );
      }

      /*
       * Store result locally as a backup.
       */
      sessionStorage.setItem("resume_analysis_result", JSON.stringify(data));

      /*
       * Navigate to result page.
       *
       * The actual result is also passed through
       * React Router state.
       */
      navigate("/dashboard/analyze/result", {
        state: {
          result: data,
          fileName: file.name,
        },
      });
    } catch (err) {
      console.error("Resume analysis error:", err);

      setError(err.message || "Unable to analyze the resume.");
    } finally {
      setLoading(false);
    }
  };

  const formatFileSize = (bytes) => {
    if (!bytes) {
      return "0 Bytes";
    }

    const mb = bytes / (1024 * 1024);

    return `${mb.toFixed(2)} MB`;
  };

  return (
    <Stack spacing={4}>
      <Box>
        <Stack direction="row" spacing={1} alignItems="center" mb={1}>
          <Button
            startIcon={<MdArrowBack />}
            onClick={() => navigate("/dashboard/analyze")}
          >
            Back
          </Button>
        </Stack>

        <Typography variant="h4" fontWeight={800}>
          Upload Your Resume
        </Typography>

        <Typography color="text.secondary" mt={1}>
          Upload your resume in PDF format and let our AI analyze your career
          profile.
        </Typography>
      </Box>

      {backendStatus === "connected" && (
        <Alert severity="success" icon={<MdCheckCircle />}>
          Backend connected successfully.
        </Alert>
      )}

      {backendStatus === "checking" && (
        <Alert severity="info">Checking AI backend connection...</Alert>
      )}

      {backendStatus === "error" && (
        <Alert
          severity="error"
          action={
            <Button color="inherit" size="small" onClick={checkHealth}>
              Retry
            </Button>
          }
        >
          Backend connection failed.
        </Alert>
      )}

      {error && (
        <Alert severity="error" onClose={() => setError("")}>
          {error}
        </Alert>
      )}

      <Box
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragEnter={handleDragOver}
        onDragLeave={handleDragLeave}
        sx={{
          position: "relative",

          minHeight: 360,

          display: "flex",
          alignItems: "center",
          justifyContent: "center",

          p: 4,

          borderRadius: 4,

          border: dragActive
            ? `2px dashed ${brandColors.primary}`
            : "2px dashed rgba(100,116,139,.30)",

          background: dragActive ? "rgba(37,99,235,.06)" : "transparent",

          transition: "all .2s ease",
        }}
      >
        <Stack alignItems="center" textAlign="center" spacing={2}>
          <Box
            sx={{
              width: 90,
              height: 90,
              borderRadius: "50%",

              display: "flex",
              alignItems: "center",
              justifyContent: "center",

              background:
                "linear-gradient(135deg, rgba(37,99,235,.12), rgba(124,58,237,.12))",

              color: brandColors.primary,
            }}
          >
            <MdCloudUpload size={48} />
          </Box>

          <Typography variant="h5" fontWeight={800}>
            Drag & Drop Your Resume
          </Typography>

          <Typography color="text.secondary">
            or choose a PDF file from your computer
          </Typography>

          <Button
            component="label"
            variant="outlined"
            startIcon={<MdUploadFile />}
          >
            Choose PDF
            <input
              type="file"
              hidden
              accept=".pdf,application/pdf"
              onChange={handleInputChange}
            />
          </Button>

          <Typography variant="caption" color="text.secondary">
            PDF only • Maximum 5 MB
          </Typography>
        </Stack>
      </Box>

      {file && (
        <Box
          sx={{
            p: 3,
            borderRadius: 3,

            border: "1px solid rgba(15,23,42,.08)",
          }}
        >
          <Stack
            direction={{
              xs: "column",
              sm: "row",
            }}
            spacing={2}
            alignItems={{
              xs: "flex-start",
              sm: "center",
            }}
          >
            <Box
              sx={{
                width: 52,
                height: 52,
                borderRadius: 2,

                display: "flex",
                alignItems: "center",
                justifyContent: "center",

                background: "rgba(37,99,235,.10)",

                color: brandColors.primary,
              }}
            >
              <MdDescription size={28} />
            </Box>

            <Box
              sx={{
                flex: 1,
                minWidth: 0,
              }}
            >
              <Typography
                fontWeight={700}
                sx={{
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
              >
                {file.name}
              </Typography>

              <Typography variant="body2" color="text.secondary">
                {formatFileSize(file.size)}
              </Typography>
            </Box>

            <IconButton
              color="error"
              onClick={() => {
                setFile(null);
                setError("");
              }}
            >
              <MdDelete />
            </IconButton>
          </Stack>
        </Box>
      )}

      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
        }}
      >
        <Button
          variant="contained"
          size="large"
          disabled={!file || loading || backendStatus === "checking"}
          onClick={handleAnalyze}
          startIcon={loading ? undefined : <MdAutoAwesome />}
          sx={{
            minWidth: 220,
          }}
        >
          {loading ? "Analyzing..." : "Analyze Resume"}
        </Button>
      </Box>

      {loading && (
        <Box>
          <LinearProgress />

          <Typography
            variant="body2"
            color="text.secondary"
            textAlign="center"
            mt={1}
          >
            Extracting text and analyzing your resume...
          </Typography>
        </Box>
      )}

      <Box
        sx={{
          p: 3,
          borderRadius: 3,

          background: "rgba(37,99,235,.05)",
        }}
      >
        <Stack direction="row" spacing={2} alignItems="flex-start">
          <MdLightbulb size={26} color={brandColors.primary} />

          <Box>
            <Typography fontWeight={700}>For the best results</Typography>

            <Typography variant="body2" color="text.secondary" mt={0.5}>
              Use a clear PDF resume containing your skills, education, work
              experience, projects, and technical knowledge.
            </Typography>
          </Box>
        </Stack>
      </Box>
    </Stack>
  );
}

function ResumeResult() {
  const navigate = useNavigate();
  const location = useLocation();
  const reportRef = useRef(null);

  const [result, setResult] = useState(location.state?.result || null);
  const [fileName, setFileName] = useState(location.state?.fileName || "");
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (result) return;
    try {
      const saved = sessionStorage.getItem("resume_analysis_result");
      if (saved) setResult(JSON.parse(saved));
    } catch (err) {
      console.error("Unable to restore result:", err);
    }
  }, [result]);

  useEffect(() => {
    if (location.state?.fileName) setFileName(location.state.fileName);
  }, [location.state]);

  // ── SINGLE-SHEET PDF EXPORT (scales to fit one page) ──
  const handleExport = async () => {
    if (!reportRef.current) {
      setError("Unable to export the result.");
      return;
    }
    setExporting(true);
    setError("");
    try {
      const canvas = await html2canvas(reportRef.current, {
        scale: 2,
        useCORS: true,
        backgroundColor: "#ffffff",
      });
      const imageData = canvas.toDataURL("image/png");
      const pdf = new jsPDF("p", "mm", "a4");
      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();

      // Scale the whole canvas down to fit within ONE page, no splitting
      const widthRatio = pageWidth / canvas.width;
      const heightRatio = pageHeight / canvas.height;
      const ratio = Math.min(widthRatio, heightRatio);

      const imgWidth = canvas.width * ratio;
      const imgHeight = canvas.height * ratio;
      const x = (pageWidth - imgWidth) / 2;
      const y = 0;

      pdf.addImage(imageData, "PNG", x, y, imgWidth, imgHeight);
      pdf.save("career-ai-resume-analysis.pdf");
    } catch (err) {
      console.error("PDF export failed:", err);
      setError(err.message || "Failed to export PDF.");
    } finally {
      setExporting(false);
    }
  };

  if (!result) {
    return (
      <Stack spacing={3} alignItems="center" sx={{ py: 8 }}>
        <MdDescription size={64} color={brandColors.primary} />
