/* ============================================================
SETTINGS
============================================================ */

function Settings() {
  const { mode, toggleMode } = useThemeMode();

  const [emailNotifications, setEmailNotifications] = useState(true);

  const [interviewReminders, setInterviewReminders] = useState(true);

  const [resumeSuggestions, setResumeSuggestions] = useState(true);

  const [saved, setSaved] = useState(false);

  useEffect(() => {
    try {
      const savedSettings = localStorage.getItem("career_ai_settings");

      if (!savedSettings) {
        return;
      }

      const settings = JSON.parse(savedSettings);

      if (typeof settings.emailNotifications === "boolean") {
        setEmailNotifications(settings.emailNotifications);
      }

      if (typeof settings.interviewReminders === "boolean") {
        setInterviewReminders(settings.interviewReminders);
      }

      if (typeof settings.resumeSuggestions === "boolean") {
        setResumeSuggestions(settings.resumeSuggestions);
      }
    } catch (error) {
      console.error("Unable to load settings:", error);
    }
  }, []);

  const handleSave = () => {
    localStorage.setItem(
      "career_ai_settings",
      JSON.stringify({
        emailNotifications,
        interviewReminders,
        resumeSuggestions,
      }),
    );

    setSaved(true);

    setTimeout(() => {
      setSaved(false);
    }, 2500);
  };

  return (
    <Stack spacing={4}>
      <Box>
        <Typography variant="h4" fontWeight={800}>
          Settings
        </Typography>

        <Typography color="text.secondary" mt={1}>
          Customize your Career AI experience.
        </Typography>
      </Box>

      {saved && (
        <Alert severity="success" icon={<MdCheckCircle />}>
          Settings saved successfully.
        </Alert>
      )}

      <Box
        sx={{
          maxWidth: 800,
          width: "100%",
          mx: "auto",
        }}
      >
        <Stack spacing={2}>
          <Box
            sx={{
              p: 3,
              borderRadius: 3,
              border: "1px solid rgba(15,23,42,.08)",
            }}
          >
            <Stack
              direction="row"
              spacing={2}
              alignItems="center"
              justifyContent="space-between"
            >
              <Stack direction="row" spacing={2} alignItems="center">
                {mode === "dark" ? (
                  <MdDarkMode size={25} />
                ) : (
                  <MdLightMode size={25} />
                )}

                <Box>
                  <Typography fontWeight={800}>Appearance</Typography>

                  <Typography variant="body2" color="text.secondary">
                    Switch between light and dark mode.
                  </Typography>
                </Box>
              </Stack>

              <Switch checked={mode === "dark"} onChange={toggleMode} />
            </Stack>
          </Box>

          <Box
            sx={{
              p: 3,
              borderRadius: 3,
              border: "1px solid rgba(15,23,42,.08)",
            }}
          >
            <Typography variant="h6" fontWeight={800} mb={2}>
              Notifications
            </Typography>

            <Stack spacing={1}>
              <FormControlLabel
                control={
                  <Switch
                    checked={emailNotifications}
                    onChange={(event) =>
                      setEmailNotifications(event.target.checked)
                    }
                  />
                }
                label="Email notifications"
              />

              <FormControlLabel
                control={
                  <Switch
                    checked={interviewReminders}
                    onChange={(event) =>
                      setInterviewReminders(event.target.checked)
                    }
                  />
                }
                label="Interview reminders"
              />

              <FormControlLabel
                control={
                  <Switch
                    checked={resumeSuggestions}
                    onChange={(event) =>
                      setResumeSuggestions(event.target.checked)
                    }
                  />
                }
                label="Resume recommendations"
              />
            </Stack>
          </Box>

          <Box
            sx={{
              display: "flex",
              justifyContent: "flex-end",
            }}
          >
            <Button
              variant="contained"
              startIcon={<MdSave />}
              onClick={handleSave}
            >
              Save Settings
            </Button>
          </Box>
        </Stack>
      </Box>
    </Stack>
  );
}

